def load() -> pd.DataFrame:
    import pandas as pd
    path = 'data/archeology/input/roman_cities.csv'
    return pd.read_csv(path)

def process(romanCities):
    import pandas as pd
    import numpy as np

    df = romanCities.copy()
    greece = df[df['Country'].astype(str).str.strip() == 'Greece']

    def parse_rank(val):
        if pd.isna(val):
            return np.nan
        s = str(val).strip()
        if s == '' or s == '-':
            return np.nan
        if 'or' in s:
            parts = [p.strip() for p in s.split('or')]
            nums = []
            for p in parts:
                try:
                    nums.append(float(p))
                except Exception:
                    pass
            return float(np.mean(nums)) if nums else np.nan
        try:
            return float(s)
        except Exception:
            return np.nan

    greece['rankNum'] = greece['Barrington Atlas Rank'].map(parse_rank)
    avg_rank = greece['rankNum'].mean()

    return pd.DataFrame([{
        'avg_rank': avg_rank,
        'n_cities': len(greece),
        'n_rank_nonnull': int(greece['rankNum'].notna().sum())
    }])
